import{_ as t,c as n,o,ae as a}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse('{"title":"Create Invoice","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-create-invoice","title":"Create Invoice","description":"Create an invoice for one or more order items.","query":"mutation CreateInvoice($input: createAdminInvoiceInput!) {\\n  createAdminInvoice(input: $input) {\\n    adminInvoice {\\n      id\\n      _id\\n      incrementId\\n      orderIncrementId\\n      state\\n      emailSent\\n      totalQty\\n\\n      orderCurrencyCode\\n      baseCurrencyCode\\n      channelCurrencyCode\\n\\n      subTotal\\n      formattedSubTotal\\n      baseSubTotal\\n      formattedBaseSubTotal\\n      subTotalInclTax\\n      formattedSubTotalInclTax\\n      baseSubTotalInclTax\\n      formattedBaseSubTotalInclTax\\n\\n      grandTotal\\n      formattedGrandTotal\\n      baseGrandTotal\\n      formattedBaseGrandTotal\\n\\n      taxAmount\\n      formattedTaxAmount\\n      baseTaxAmount\\n      formattedBaseTaxAmount\\n\\n      discountAmount\\n      formattedDiscountAmount\\n      baseDiscountAmount\\n      formattedBaseDiscountAmount\\n\\n      shippingAmount\\n      formattedShippingAmount\\n      baseShippingAmount\\n      formattedBaseShippingAmount\\n      shippingAmountInclTax\\n      formattedShippingAmountInclTax\\n      baseShippingAmountInclTax\\n      formattedBaseShippingAmountInclTax\\n      shippingTaxAmount\\n      formattedShippingTaxAmount\\n      baseShippingTaxAmount\\n      formattedBaseShippingTaxAmount\\n\\n      transactionId\\n      reminders\\n      nextReminderAt\\n      createdAt\\n      updatedAt\\n\\n      orderStatus\\n      orderStatusLabel\\n      orderDate\\n      channelName\\n      customerName\\n      customerEmail\\n\\n      order {\\n        _id\\n        incrementId\\n        status\\n        statusLabel\\n        channelName\\n        customerEmail\\n        customerFirstName\\n        customerLastName\\n      }\\n    }\\n  }\\n}\\n","variables":"{\\n    \\"input\\": {\\n        \\"orderId\\": 2392,\\n        \\"items\\": [\\n            { \\"orderItemId\\": 42, \\"quantity\\": 3 },\\n            { \\"orderItemId\\": 43, \\"quantity\\": 1 }\\n        ],\\n        \\"canCreateTransaction\\": true\\n    }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminInvoice\\": {\\n      \\"adminInvoice\\": {\\n        \\"id\\": \\"/api/admin/invoices/88\\",\\n        \\"_id\\": 88,\\n        \\"incrementId\\": \\"88\\",\\n        \\"orderIncrementId\\": \\"2392\\",\\n        \\"state\\": \\"paid\\",\\n        \\"emailSent\\": false,\\n        \\"totalQty\\": 4,\\n\\n        \\"orderCurrencyCode\\": \\"USD\\",\\n        \\"baseCurrencyCode\\": \\"USD\\",\\n        \\"channelCurrencyCode\\": \\"USD\\",\\n\\n        \\"subTotal\\": 14000,\\n        \\"formattedSubTotal\\": \\"$14,000.00\\",\\n        \\"baseSubTotal\\": 14000,\\n        \\"formattedBaseSubTotal\\": \\"$14,000.00\\",\\n        \\"subTotalInclTax\\": 14000,\\n        \\"formattedSubTotalInclTax\\": \\"$14,000.00\\",\\n        \\"baseSubTotalInclTax\\": 14000,\\n        \\"formattedBaseSubTotalInclTax\\": \\"$14,000.00\\",\\n\\n        \\"grandTotal\\": 14000,\\n        \\"formattedGrandTotal\\": \\"$14,000.00\\",\\n        \\"baseGrandTotal\\": 14000,\\n        \\"formattedBaseGrandTotal\\": \\"$14,000.00\\",\\n\\n        \\"taxAmount\\": 0,\\n        \\"formattedTaxAmount\\": \\"$0.00\\",\\n        \\"baseTaxAmount\\": 0,\\n        \\"formattedBaseTaxAmount\\": \\"$0.00\\",\\n\\n        \\"discountAmount\\": 0,\\n        \\"formattedDiscountAmount\\": \\"$0.00\\",\\n        \\"baseDiscountAmount\\": 0,\\n        \\"formattedBaseDiscountAmount\\": \\"$0.00\\",\\n\\n        \\"shippingAmount\\": 0,\\n        \\"formattedShippingAmount\\": \\"$0.00\\",\\n        \\"baseShippingAmount\\": 0,\\n        \\"formattedBaseShippingAmount\\": \\"$0.00\\",\\n        \\"shippingAmountInclTax\\": 0,\\n        \\"formattedShippingAmountInclTax\\": \\"$0.00\\",\\n        \\"baseShippingAmountInclTax\\": 0,\\n        \\"formattedBaseShippingAmountInclTax\\": \\"$0.00\\",\\n        \\"shippingTaxAmount\\": 0,\\n        \\"formattedShippingTaxAmount\\": \\"$0.00\\",\\n        \\"baseShippingTaxAmount\\": 0,\\n        \\"formattedBaseShippingTaxAmount\\": \\"$0.00\\",\\n\\n        \\"transactionId\\": null,\\n        \\"reminders\\": 0,\\n        \\"nextReminderAt\\": null,\\n        \\"createdAt\\": \\"2026-05-21 11:40:08\\",\\n        \\"updatedAt\\": \\"2026-05-21 11:40:08\\",\\n\\n        \\"orderStatus\\": \\"processing\\",\\n        \\"orderStatusLabel\\": \\"Processing\\",\\n        \\"orderDate\\": \\"2026-05-19 13:13:29\\",\\n        \\"channelName\\": \\"bagisto store\\",\\n        \\"customerName\\": \\"Test User\\",\\n        \\"customerEmail\\": \\"admin@example.com\\",\\n\\n        \\"order\\": {\\n          \\"_id\\": 2392,\\n          \\"incrementId\\": \\"2392\\",\\n          \\"status\\": \\"processing\\",\\n          \\"statusLabel\\": \\"Processing\\",\\n          \\"channelName\\": \\"bagisto store\\",\\n          \\"customerEmail\\": \\"admin@example.com\\",\\n          \\"customerFirstName\\": \\"Test\\",\\n          \\"customerLastName\\": \\"User\\"\\n        }\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/orders/create-invoice.md","filePath":"api/graphql-api/admin/sales/orders/create-invoice.md"}'),r={name:"api/graphql-api/admin/sales/orders/create-invoice.md"};function d(i,e,s,c,l,m){return o(),n("div",null,e[0]||(e[0]=[a('<h1 id="create-invoice" tabindex="-1">Create Invoice <a class="header-anchor" href="#create-invoice" aria-label="Permalink to &quot;Create Invoice&quot;">​</a></h1><p>Creates an invoice for one or more order items. The same eligibility checks as the admin Invoice screen apply (the order must not be closed, marked fraud, or paid through PayPal Standard — those orders are hard-blocked from invoicing). Each item&#39;s requested quantity is validated against its still-invoiceable quantity, <code>qty_to_invoice</code>, before the invoice is created.</p><p>The mutation returns the created invoice&#39;s <strong>scalar fields</strong> plus the linked <strong><code>order</code></strong> object (the full order resource — see <a href="/api/graphql-api/admin/sales/orders/order-detail.html">Get Order Detail</a> for every <code>order</code> sub-field). The nested <strong><code>items</code></strong> connection and the <strong><code>order { addresses { edges { node } } }</code></strong> connection are <strong>not</strong> resolved on a mutation payload — fetch them with a follow-up <a href="/api/graphql-api/admin/sales/orders/get-invoice.html"><code>adminInvoice(id:)</code></a> query (or REST <code>GET /api/admin/invoices/{id}</code>) using the returned <code>id</code> / <code>_id</code>.</p><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p>The example targets an order with invoiceable items. If your order has no items with <code>qty_to_invoice &gt; 0</code> (already fully invoiced / closed / fraud / paypal_standard payment method) the mutation returns <em>&quot;There is nothing to invoice on this order.&quot;</em> — pick an order with outstanding qty to invoice.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>createAdminInvoice</code></td><td>Mutation</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>Int!</code></td><td>The order to invoice.</td></tr><tr><td><code>items</code></td><td><code>[{ orderItemId, quantity }]!</code></td><td>One entry per order item, with the quantity to invoice. Each <code>quantity</code> must be ≤ that item&#39;s still-invoiceable <code>qty_to_invoice</code>.</td></tr><tr><td><code>canCreateTransaction</code></td><td><code>Boolean</code></td><td>Optional, default <code>false</code>. The admin <strong>Create Transaction</strong> checkbox — when <code>true</code>, also records an order transaction for the invoice amount against the order&#39;s payment method.</td></tr></tbody></table><h2 id="response-shape-notes" tabindex="-1">Response shape notes <a class="header-anchor" href="#response-shape-notes" aria-label="Permalink to &quot;Response shape notes&quot;">​</a></h2><ul><li>The mutation payload resolves the invoice&#39;s <strong>scalar fields</strong> + the <code>order</code> object&#39;s <strong>scalar fields</strong> (it&#39;s the full order resource — <code>_id</code>, <code>incrementId</code>, <code>status</code>, <code>statusLabel</code>, <code>channelName</code>, <code>customerEmail</code>, <code>customerFirstName</code>, <code>customerLastName</code>, totals, … — see <a href="/api/graphql-api/admin/sales/orders/order-detail.html">Get Order Detail</a> for the complete list). It does <strong>not</strong> resolve the <code>items</code> connection or <code>order { addresses }</code> — those are available on the <a href="/api/graphql-api/admin/sales/orders/get-invoice.html"><code>adminInvoice(id:)</code></a> detail query (where <code>items { edges { node } }</code> and <code>order { addresses { edges { node } } }</code> resolve fully).</li><li>There is <strong>no top-level <code>orderId</code></strong> — the order id is <code>order { _id }</code>.</li><li><code>id</code> is the resource IRI (<code>/api/admin/invoices/88</code>); <code>_id</code> is the numeric id.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Message</th></tr></thead><tbody><tr><td>Order is <code>closed</code></td><td>Closed orders cannot be invoiced.</td></tr><tr><td>Order is <code>fraud</code></td><td>Fraud orders cannot be invoiced.</td></tr><tr><td>Order paid with PayPal Standard</td><td>Invoices cannot be created for orders paid through PayPal Standard.</td></tr><tr><td>Nothing to invoice</td><td>There is nothing to invoice on this order.</td></tr><tr><td>No permission</td><td>You do not have permission to create invoices.</td></tr><tr><td>Items missing</td><td>At least one item with a positive quantity is required.</td></tr><tr><td>Qty exceeds available</td><td>Requested quantity exceeds the available quantity for the given SKU (the message names the SKU and both quantities).</td></tr><tr><td>Save failed</td><td>Could not create the invoice.</td></tr></tbody></table>',12)]))}const p=t(r,[["render",d]]);export{h as __pageData,p as default};
